class CharacterPair:
    def __init__(self, chr, value, idx):
        self.chr = chr
        self.value = value
        self.idx = idx

def swapChars(chArr, vals, i):
    chArr[i], chArr[len(chArr) - i - 1] = chArr[len(chArr) - i - 1], chArr[i]
    vals[i], vals[len(vals) - i - 1] = vals[len(vals) - i - 1], vals[i]

def checkAntiPalindrome(chArr):
    length = len(chArr)
    for i in range(length // 2):
        if chArr[i] == chArr[length - i - 1]:
            return False
    return True

mismatchChars = []
pairs = []

for i in range(n // 2):
    if vals[i] > vals[n - i - 1]:
        swapChars(chArr, vals, i)
    cp = CharacterPair(chArr[i], vals[i], i)
    if chArr[i] == chArr[n - i - 1]:
        mismatchChars.append(cp)
    pairs.append(cp)

pairs.sort(key=lambda c: c.value)

diffSum = 0
if not checkAntiPalindrome(chArr):
    if len(mismatchChars) == 1:
        wrong = mismatchChars[0]
        for cp in pairs:
            if cp.chr != wrong.chr and chArr[n - cp.idx - 1] != wrong.chr:
                diffSum = wrong.value + cp.value
                break
    elif len(mismatchChars) > 1:
        countMap = {}
        for cp in mismatchChars:
            countMap[cp.chr] = countMap.get(cp.chr, 0) + 1
        maxCount = max(countMap.values())
        appendList = []
        while maxCount * 2 > len(mismatchChars) + len(appendList):
            maxChar = max(countMap.items(), key=lambda item: item[1])[0]
            for cp in pairs:
                if cp.chr != maxChar and chArr[n - cp.idx - 1] != maxChar and cp not in mismatchChars and cp not in appendList:
                    appendList.append(cp)
                    break
        diffSum = sum(c.value for c in mismatchChars) + sum(c.value for c in appendList)

totalSum = sum(vals)
print(totalSum - diffSum)

